import {escapeHTML as e,money as m,link as l} from './components.js';

const imageFor=p=>p?.photo||(p?'./assets/'+(p.image.startsWith('market-')?p.image.replace('market-','market-large-'):p.image)+'.svg':'./assets/product-placeholder.svg');
const cta=(path,label,light=false)=>l(path,label+' <span aria-hidden="true">↗</span>','home-cta'+(light?' light':''));

function categoryIcon(name){
  const shapes=[
    [/điện tử|công nghệ|điện thoại/i,'<path d="M5 14v-3a7 7 0 0 1 14 0v3"/><rect x="3" y="12" width="5" height="8" rx="2"/><rect x="16" y="12" width="5" height="8" rx="2"/>'],
    [/thời trang|quần áo/i,'<path d="m8 3-5 3-2 5 5 2v8h12v-8l5-2-2-5-5-3a4 4 0 0 1-8 0Z"/>'],
    [/nhà cửa|gia dụng|đời sống|nội thất/i,'<path d="m3 10 9-7 9 7M5 9v12h14V9M9 21v-8h6v8"/>'],
    [/làm đẹp|mỹ phẩm|chăm sóc/i,'<path d="M9 8V3h6v5M8 8h8l2 4v9H6v-9Z"/><path d="M9 15h6M9 18h6M10 5h4"/>'],
    [/sách|văn phòng|học tập/i,'<path d="M12 5C9 3 5 3 2 4v16c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1Zm0 0v16M5 8h3M5 12h3M16 8h3M16 12h3"/>'],
    [/thể thao|tập luyện/i,'<path d="M7 7v10M4 9v6M17 7v10M20 9v6M7 12h10M2 12h2M20 12h2"/>'],
    [/thực phẩm|ăn uống/i,'<path d="M5 3v6a3 3 0 0 0 6 0V3M8 3v18M19 21V3c-4 2-4 9 0 9"/>'],
    [/thú cưng/i,'<ellipse cx="12" cy="16" rx="5" ry="4"/><ellipse cx="4" cy="10" rx="2" ry="3"/><ellipse cx="20" cy="10" rx="2" ry="3"/><ellipse cx="9" cy="5" rx="2" ry="3"/><ellipse cx="15" cy="5" rx="2" ry="3"/>']
  ];
  const shape=shapes.find(([pattern])=>pattern.test(name))?.[1]||'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>';
  return `<span class="home-category-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" focusable="false">${shape}</svg></span>`;
}

export function renderHome(s,{grid,shopCard,published}){
  const products=s.products.filter(published),available=products.filter(p=>p.stock>0);
  const featured=[...available].sort((a,b)=>(b.reviewCount||0)-(a.reviewCount||0)||(b.rating||0)-(a.rating||0)).slice(0,5);
  const stores=s.shops.filter(x=>x.status==='Đang hoạt động');
  const coupons=s.coupons.filter(c=>c.enabled&&c.start<=s.businessDate&&c.end>=s.businessDate&&c.remaining>0&&(!c.shopId||stores.some(x=>x.id===c.shopId)));
  const offer=coupons.sort((a,b)=>b.amount-a.amount)[0];
  const categories=s.categories.filter(c=>products.some(p=>p.category===c));
  const first=featured[0],second=featured.find(p=>p.category!==first?.category)||featured[1];
  const slides=[{eyebrow:'CHỢ PTIT · MUA SẮM ĐA NGÀNH',title:'Một điểm đến.<br>Nhiều điều đáng chọn.',description:'Từ công nghệ, thời trang đến đồ dùng mỗi ngày. Khám phá sản phẩm từ các gian hàng đã được xét duyệt.',path:'products',button:'Bắt đầu khám phá',product:first,theme:'discovery',note:first?first.name:'Khám phá các ngành hàng'}];
  if(first)slides.push({eyebrow:'SẢN PHẨM NỔI BẬT',title:e(first.name),description:e(s.shops.find(x=>x.id===first.shopId)?.name||'')+' · '+e(first.category),path:'product/'+first.id,button:'Xem sản phẩm',product:first,theme:'featured',note:'Giá từ '+m(first.price),price:m(first.price)});
  if(offer)slides.push({eyebrow:'ƯU ĐÃI ĐANG ÁP DỤNG',title:'Thêm lựa chọn.<br>Thêm ưu đãi.',description:`Giảm ${m(offer.amount)} cho tiền hàng từ ${m(offer.minimum)}. ${offer.shopId?e(stores.find(x=>x.id===offer.shopId)?.name):'Áp dụng trên sàn'} · Trong giới hạn lượt sử dụng.`,path:'vouchers',button:'Xem điều kiện ưu đãi',product:available.find(p=>!offer.shopId||p.shopId===offer.shopId)||second,theme:'offer',note:'Mã '+offer.code,code:offer.code});
  else if(second)slides.push({eyebrow:e(second.category.toUpperCase()),title:'Chọn điều bạn thích.<br>Tìm đúng điều bạn cần.',description:`Khám phá ${e(second.category.toLowerCase())} và những lựa chọn phù hợp với nhu cầu của bạn.`,path:'products?category='+encodeURIComponent(second.category),button:'Khám phá ngành hàng',product:second,theme:'category',note:second.name});
  else slides.push({eyebrow:'GIAN HÀNG TRÊN CHỢ PTIT',title:'Kết nối người mua.<br>Đồng hành người bán.',description:'Tìm hiểu từng gian hàng, khám phá sản phẩm và theo dõi riêng mỗi đơn mua.',path:'shops',button:'Khám phá gian hàng',theme:'category',note:'Mua sắm từ nhiều gian hàng'});
  const carousel=`<section class="home-carousel" aria-label="Sản phẩm nổi bật và ưu đãi" aria-roledescription="carousel" tabindex="0">${slides.map((x,i)=>`<article class="home-slide ${x.theme}" data-slide="${i}" role="group" aria-roledescription="banner" aria-label="${i+1} / ${slides.length}" ${i?'hidden':''}><div class="home-slide-copy"><span class="home-eyebrow">${x.eyebrow}</span><h2>${x.title}</h2><p>${x.description}</p>${x.price?`<strong class="home-banner-price">${x.price}</strong>`:''}${x.code?`<span class="home-offer-code">${e(x.code)}</span>`:''}${cta(x.path,x.button)}</div><div class="home-slide-art"><div class="home-art-circle"></div><img src="${e(imageFor(x.product))}" alt="${e(x.product?.name||'Sản phẩm trên Chợ PTIT')}" width="360" height="300"><span class="home-art-caption">${e(x.note)}</span></div></article>`).join('')}<div class="home-carousel-controls"><div class="home-dots">${slides.map((_,i)=>`<button type="button" data-slide-to="${i}" aria-label="Chuyển đến banner ${i+1}" aria-current="${i===0}" class="${i===0?'selected':''}"></button>`).join('')}</div><div class="home-carousel-actions"><span data-slide-count>01 / ${String(slides.length).padStart(2,'0')}</span><button type="button" data-carousel="previous" aria-label="Banner trước">←</button><button type="button" data-carousel="next" aria-label="Banner tiếp theo">→</button><button type="button" data-carousel="pause" aria-label="Tạm dừng xoay banner" aria-pressed="false">Ⅱ</button></div></div><span class="sr-only" aria-live="polite" data-carousel-status></span></section>`;
  const miniTop=offer?`<aside class="home-mini offer"><div><span class="home-eyebrow">ƯU ĐÃI HIỆN CÓ</span><h2>Giảm ${m(offer.amount)}</h2><p>Tiền hàng từ ${m(offer.minimum)}</p>${cta('vouchers','Xem mã ưu đãi')}</div><span class="home-mini-code">${e(offer.code)}</span></aside>`:`<aside class="home-mini category"><div><span class="home-eyebrow">KHÁM PHÁ MỖI NGÀY</span><h2>${e(second?.category||'Nhiều ngành hàng')}</h2><p>Những lựa chọn cho phong cách riêng.</p>${cta(second?'products?category='+encodeURIComponent(second.category):'products','Xem sản phẩm')}</div>${second?`<img src="${e(imageFor(second))}" alt="${e(second.name)}" width="132" height="110">`:''}</aside>`;
  const benefits=[['01','Đa dạng gian hàng','Khám phá và chọn nơi mua phù hợp','shops'],['02','Thanh toán COD','Thanh toán khi nhận hàng','policies'],['03','Theo dõi từng đơn','Trạng thái riêng cho mỗi gian hàng','orders'],['04','Chính sách rõ ràng','Xem điều kiện mua hàng và đổi trả','policies']];
  const categoryLinks=(categories.length?categories:s.categories).map((c,i)=>l('products?category='+encodeURIComponent(c),`${categoryIcon(c)}<strong>${e(c)}</strong><small>${products.filter(p=>p.category===c).length} sản phẩm <span aria-hidden="true">↗</span></small>`)).join('');
  const categoryBanners=categories.slice(0,2).map((c,i)=>{const p=available.find(p=>p.category===c)||products.find(p=>p.category===c);return `<article class="home-category-banner ${i?'warm':''}"><div><span class="home-eyebrow">KHÁM PHÁ ${String(i+1).padStart(2,'0')}</span><h2>${e(c)}</h2><p>${i?'Lựa chọn phù hợp. Phong cách riêng.':'Sản phẩm bạn cần cho mỗi ngày.'}</p>${cta('products?category='+encodeURIComponent(c),'Khám phá ngay')}</div><img src="${e(imageFor(p))}" width="216" height="180" alt="${e(p?.name||c)}"></article>`;}).join('');
  return `<main id="main" tabindex="-1" class="container home-main"><div class="home-page-intro"><div><span class="home-eyebrow">CHÀO MỪNG BẠN ĐẾN VỚI CHỢ PTIT</span><h1>Hôm nay, bạn muốn tìm gì?</h1></div><p>${products.length} sản phẩm · ${stores.length} gian hàng đang hoạt động</p></div><div class="home-banner-layout">${carousel}<div class="home-side-banners">${miniTop}<aside class="home-mini seller"><div><span class="home-eyebrow">BÁN HÀNG CÙNG CHỢ PTIT</span><h2>Gian hàng của bạn.<br>Cơ hội kết nối mới.</h2>${cta(s.user?.role==='seller'?'seller':'open-shop',s.user?.role==='seller'?'Vào kênh người bán':'Tìm hiểu mở gian hàng',true)}</div><span class="home-mini-mark" aria-hidden="true">↗</span></aside></div></div><div class="home-benefits">${benefits.map(([n,t,d,p])=>l(p,`<span>${n}</span><div><strong>${t}</strong><small>${d}</small></div>`)).join('')}</div><section class="home-content-section"><div class="home-section-heading"><div><span class="home-eyebrow">01 / KHÁM PHÁ THEO NHU CẦU</span><h2>Ngành hàng dành cho bạn</h2></div>${l('products','Tất cả ngành hàng ↗')}</div><div class="home-category-grid">${categoryLinks||'<p>Ngành hàng đang được cập nhật.</p>'}</div></section><section class="home-content-section"><div class="home-section-heading"><div><span class="home-eyebrow">02 / NHỮNG LỰA CHỌN ĐÁNG KHÁM PHÁ</span><h2>Sản phẩm nổi bật</h2></div>${l('products','Xem tất cả sản phẩm ↗')}</div>${grid(featured)}</section>${categoryBanners?`<div class="home-category-banners">${categoryBanners}</div>`:''}<section class="home-content-section"><div class="home-section-heading"><div><span class="home-eyebrow">03 / KẾT NỐI NGƯỜI MUA VÀ NGƯỜI BÁN</span><h2>Khám phá các gian hàng</h2></div>${l('shops','Xem tất cả gian hàng ↗')}</div><div class="market-shops">${stores.slice(0,3).map(shopCard).join('')||'<p>Chưa có gian hàng đang hoạt động.</p>'}</div></section></main>`;
}

export function mountHomeCarousel(container){
  const root=container.querySelector('.home-carousel');if(!root)return ()=>{};
  const slides=[...root.querySelectorAll('[data-slide]')],dots=[...root.querySelectorAll('[data-slide-to]')],pause=root.querySelector('[data-carousel="pause"]');
  const controller=new AbortController(),options={signal:controller.signal};
  let index=0,timer=null,hovered=false,focused=false,paused=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const pauseLabel=()=>{pause.textContent=paused?'▶':'Ⅱ';pause.setAttribute('aria-label',paused?'Tiếp tục xoay banner':'Tạm dừng xoay banner');pause.setAttribute('aria-pressed',String(paused));};
  function show(next,announce=false){index=(next+slides.length)%slides.length;slides.forEach((slide,i)=>{slide.hidden=i!==index;});dots.forEach((dot,i)=>{dot.classList.toggle('selected',i===index);dot.setAttribute('aria-current',String(i===index));});root.querySelector('[data-slide-count]').textContent=String(index+1).padStart(2,'0')+' / '+String(slides.length).padStart(2,'0');if(announce)root.querySelector('[data-carousel-status]').textContent='Banner '+(index+1)+' / '+slides.length;}
  function schedule(){clearTimeout(timer);if(paused||hovered||focused||document.hidden||slides.length<2)return;timer=setTimeout(()=>{show(index+1);schedule();},6000);}
  root.addEventListener('click',event=>{const button=event.target.closest('[data-carousel],[data-slide-to]');if(!button)return;if(button.hasAttribute('data-slide-to'))show(Number(button.dataset.slideTo),true);else if(button.dataset.carousel==='pause'){paused=!paused;pauseLabel();}else show(index+(button.dataset.carousel==='next'?1:-1),true);schedule();},options);
  root.addEventListener('keydown',event=>{if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();show(index+(event.key==='ArrowRight'?1:-1),true);schedule();}},options);
  root.addEventListener('mouseenter',()=>{hovered=true;schedule();},options);root.addEventListener('mouseleave',()=>{hovered=false;schedule();},options);
  root.addEventListener('focusin',()=>{focused=true;schedule();},options);root.addEventListener('focusout',event=>{focused=root.contains(event.relatedTarget);schedule();},options);
  document.addEventListener('visibilitychange',schedule,options);pauseLabel();schedule();
  return ()=>{clearTimeout(timer);controller.abort();};
}
